DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.payroll_terms_candidates(uuid,integer,integer)'::regprocedure) INTO def;def:=replace(def,'CASE WHEN e.employment_type=''full_time'' THEN ''month'' ELSE ''hour'' END pay_basis','CASE WHEN p.preparation->>''pay_basis'' IN (''month'',''hour'') THEN p.preparation->>''pay_basis'' WHEN e.employment_type=''full_time'' THEN ''month'' ELSE NULL END pay_basis');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_fill_terms(uuid,integer,integer,jsonb)'::regprocedure) INTO def;def:=replace(def,'candidate->>''pay_basis'' IS DISTINCT FROM c->>''pay_basis''','(candidate->>''pay_basis'' IS NOT NULL AND candidate->>''pay_basis'' IS DISTINCT FROM c->>''pay_basis'') OR COALESCE(c->>''pay_basis'','''') NOT IN (''month'',''hour'')');def:=replace(def,'''pay_basis'',candidate->>''pay_basis''','''pay_basis'',c->>''pay_basis''');EXECUTE def;
SELECT pg_get_functiondef('public.payroll_preview(uuid,integer,integer)'::regprocedure) INTO def;def:=replace(def,'''source'',source,''hours'',total_hours','''source'',source,''pay_basis'',basis,''hours'',total_hours');EXECUTE def;END $$;